import { Component, OnInit } from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import { HttpErrorResponse } from "@angular/common/http";
import { LANGUAGE_OPTIONS } from "../../constants/languages";
import type {
  OrganizationTerm,
  OrganizationTermCategory,
  OrganizationTermInterpretation,
} from "../../models/organization.model";
import { OrganizationsService } from "../../services/organizations.service";

@Component({
  selector: "app-organization-form",
  templateUrl: "./organization-form.component.html",
  styleUrls: ["./organization-form.component.scss"],
  host: {
    class: "fill-screen fill-screen--top",
    dir: "ltr",
    lang: "en",
  },
})
export class OrganizationFormComponent implements OnInit {
  readonly languageOptions = LANGUAGE_OPTIONS;

  editId = "";
  isEdit = false;
  isLoading = true;

  name = "";
  language = "en";
  translationContext = "";
  password = "";
  terms: OrganizationTermCategory[] = [];

  errorMessage = "";
  statusMessage = "";

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private organizationsService: OrganizationsService,
  ) {}

  ngOnInit(): void {
    this.route.queryParams.subscribe((params) => {
      this.editId = (params["edit"] ?? "").trim();
      this.isEdit = this.editId.length > 0;
      this.loadForm();
    });
  }

  back(): void {
    void this.router.navigate(["/config"]);
  }

  addCategory(): void {
    this.terms.push({ name: "", terms: [] });
  }

  removeCategory(index: number): void {
    this.terms.splice(index, 1);
  }

  addTerm(categoryIndex: number): void {
    const category = this.terms[categoryIndex];
    if (!category) return;
    category.terms.push({
      name: "",
      description: "",
      interpretations: [{ text: "" }],
    });
  }

  removeTerm(categoryIndex: number, termIndex: number): void {
    this.terms[categoryIndex]?.terms.splice(termIndex, 1);
  }

  addInterpretation(categoryIndex: number, termIndex: number): void {
    const term = this.terms[categoryIndex]?.terms[termIndex];
    if (!term) return;
    term.interpretations.push({ text: "" });
  }

  removeInterpretation(
    categoryIndex: number,
    termIndex: number,
    interpretationIndex: number,
  ): void {
    const term = this.terms[categoryIndex]?.terms[termIndex];
    if (!term) return;
    term.interpretations.splice(interpretationIndex, 1);
  }

  trackByIndex(index: number): number {
    return index;
  }

  onSubmit(): void {
    if (!this.name.trim()) {
      this.errorMessage = "Organization name is required.";
      this.statusMessage = "";
      return;
    }
    if (!this.translationContext.trim()) {
      this.errorMessage = "Translation context is required.";
      this.statusMessage = "";
      return;
    }
    if (!this.isEdit && !this.password) {
      this.errorMessage = "Password is required for a new organization.";
      this.statusMessage = "";
      return;
    }

    this.errorMessage = "";
    const payload = {
      name: this.name.trim(),
      language: this.language,
      translationContext: this.translationContext.trim(),
      terms: this.serializeTerms(),
    };

    if (this.isEdit) {
      this.organizationsService
        .update(this.editId, {
          ...payload,
          ...(this.password ? { password: this.password } : {}),
        })
        .subscribe({
          next: () => {
            this.statusMessage = "Organization updated.";
          },
          error: (err: HttpErrorResponse) => {
            this.errorMessage = this.httpErrorMessage(err, "Save failed");
          },
        });
      return;
    }

    this.organizationsService
      .create({ ...payload, password: this.password })
      .subscribe({
        next: () => {
          this.statusMessage = "Organization created.";
          setTimeout(() => this.back(), 600);
        },
        error: (err: HttpErrorResponse) => {
          this.errorMessage = this.httpErrorMessage(err, "Save failed");
        },
      });
  }

  private serializeTerms(): OrganizationTermCategory[] {
    return this.terms
      .map((category) => ({
        name: category.name.trim(),
        terms: category.terms
          .map((term) => this.serializeTerm(term))
          .filter((term) => term.name.length > 0),
      }))
      .filter((category) => category.name.length > 0);
  }

  private serializeTerm(term: OrganizationTerm): OrganizationTerm {
    return {
      name: term.name.trim(),
      description: term.description.trim(),
      interpretations: term.interpretations
        .map((item) => ({ text: item.text.trim() }))
        .filter((item) => item.text.length > 0),
    };
  }

  private loadForm(): void {
    if (!this.isEdit) {
      this.name = "";
      this.language = "en";
      this.translationContext = "";
      this.password = "";
      this.terms = [];
      this.isLoading = false;
      return;
    }

    this.isLoading = true;
    this.organizationsService.get(this.editId).subscribe({
      next: (data) => {
        this.name = data.organization.name;
        this.language = data.organization.language;
        this.translationContext = data.organization.translationContext;
        this.password = "";
        this.terms = this.cloneTerms(data.organization.terms ?? []);
        this.isLoading = false;
      },
      error: (err: HttpErrorResponse) => {
        this.isLoading = false;
        this.errorMessage = this.httpErrorMessage(err, "Failed to load form");
      },
    });
  }

  private cloneTerms(
    raw: OrganizationTermCategory[],
  ): OrganizationTermCategory[] {
    return raw.map((category) => ({
      name: category.name ?? "",
      terms: (category.terms ?? []).map((term) => ({
        name: term.name ?? "",
        description: term.description ?? "",
        interpretations: this.cloneInterpretations(term.interpretations),
      })),
    }));
  }

  private cloneInterpretations(
    raw: OrganizationTermInterpretation[] | undefined,
  ): OrganizationTermInterpretation[] {
    const items = (raw ?? []).map((item) => ({ text: item.text ?? "" }));
    return items.length > 0 ? items : [{ text: "" }];
  }

  private httpErrorMessage(err: HttpErrorResponse, fallback: string): string {
    const body = err.error as { message?: string; error?: string } | undefined;
    return body?.message ?? body?.error ?? err.message ?? fallback;
  }
}
<div class="config-shell config-shell--wide">
  <div class="config-header">
    <h1>{{ isEdit ? "Edit organization" : "Create organization" }}</h1>
    <button type="button" class="btn-secondary" (click)="back()">
      Back to configuration
    </button>
  </div>

  <p class="error" *ngIf="errorMessage">{{ errorMessage }}</p>
  <p class="status-msg" *ngIf="statusMessage">{{ statusMessage }}</p>

  <div class="config-card" *ngIf="isLoading">
    <p class="muted">Loading…</p>
  </div>

  <div class="config-card" *ngIf="!isLoading">
    <form (ngSubmit)="onSubmit()">
      <section class="config-section">
        <h2>{{ isEdit ? "Organization details" : "New organization" }}</h2>
        <div class="field">
          <label for="org-name">Organization name</label>
          <input
            id="org-name"
            name="name"
            type="text"
            required
            maxlength="120"
            [(ngModel)]="name"
          />
          <p class="field-hint">Display name shown when agents choose this organization.</p>
        </div>
        <div class="field">
          <label for="org-language">Organization language</label>
          <select id="org-language" name="language" required [(ngModel)]="language">
            <option *ngFor="let opt of languageOptions" [value]="opt.value">
              {{ opt.label }}
            </option>
          </select>
          <p class="field-hint">Target language for incoming chat translations.</p>
        </div>
        <div class="field">
          <label for="org-context">Translation context</label>
          <textarea
            id="org-context"
            name="translationContext"
            rows="5"
            required
            [(ngModel)]="translationContext"
          ></textarea>
          <p class="field-hint">Instructions or tone used when translating messages.</p>
        </div>
        <div class="field">
          <label for="org-password">Organization password</label>
          <input
            id="org-password"
            name="password"
            type="password"
            autocomplete="new-password"
            [required]="!isEdit"
            [(ngModel)]="password"
          />
          <p class="field-hint" *ngIf="isEdit">
            Leave blank to keep the current password. Required when connecting to
            this organization.
          </p>
          <p class="field-hint" *ngIf="!isEdit">
            Agents must enter this password to connect to the organization.
          </p>
        </div>
      </section>

      <section class="config-section terms-section">
        <div class="terms-section__header">
          <h2>Terms glossary</h2>
          <button type="button" class="btn-secondary" (click)="addCategory()">
            Add category
          </button>
        </div>
        <p class="field-hint terms-section__intro">
          Optional categories of terms with descriptions and interpretations. Not
          used by translation yet — stored for this organization only.
        </p>

        <p class="muted" *ngIf="terms.length === 0">No categories yet.</p>

        <article
          class="term-category"
          *ngFor="let category of terms; let ci = index; trackBy: trackByIndex"
        >
          <div class="term-category__header">
            <div class="field term-category__name">
              <label [for]="'cat-name-' + ci">Category name</label>
              <input
                [id]="'cat-name-' + ci"
                type="text"
                maxlength="120"
                [(ngModel)]="category.name"
                [name]="'cat-name-' + ci"
              />
            </div>
            <button
              type="button"
              class="btn-danger btn-small"
              (click)="removeCategory(ci)"
            >
              Remove category
            </button>
          </div>

          <p class="muted" *ngIf="category.terms.length === 0">No terms in this category.</p>

          <div
            class="term-item"
            *ngFor="let term of category.terms; let ti = index; trackBy: trackByIndex"
          >
            <div class="term-item__header">
              <h3>Term {{ ti + 1 }}</h3>
              <button
                type="button"
                class="btn-danger btn-small"
                (click)="removeTerm(ci, ti)"
              >
                Remove term
              </button>
            </div>
            <div class="field">
              <label [for]="'term-name-' + ci + '-' + ti">Term name</label>
              <input
                [id]="'term-name-' + ci + '-' + ti"
                type="text"
                maxlength="120"
                [(ngModel)]="term.name"
                [name]="'term-name-' + ci + '-' + ti"
              />
            </div>
            <div class="field">
              <label [for]="'term-desc-' + ci + '-' + ti">Description</label>
              <textarea
                [id]="'term-desc-' + ci + '-' + ti"
                rows="2"
                maxlength="2000"
                [(ngModel)]="term.description"
                [name]="'term-desc-' + ci + '-' + ti"
              ></textarea>
            </div>
            <div class="interpretations-block">
              <div class="interpretations-block__header">
                <span class="interpretations-block__label">Interpretations</span>
                <button
                  type="button"
                  class="btn-secondary btn-small"
                  (click)="addInterpretation(ci, ti)"
                >
                  Add interpretation
                </button>
              </div>
              <p class="muted" *ngIf="term.interpretations.length === 0">
                No interpretations.
              </p>
              <div
                class="interpretation-row"
                *ngFor="
                  let interp of term.interpretations;
                  let ii = index;
                  trackBy: trackByIndex
                "
              >
                <input
                  type="text"
                  maxlength="500"
                  placeholder="Interpretation"
                  [(ngModel)]="interp.text"
                  [name]="'interp-' + ci + '-' + ti + '-' + ii"
                />
                <button
                  type="button"
                  class="btn-danger btn-small"
                  (click)="removeInterpretation(ci, ti, ii)"
                  [disabled]="term.interpretations.length <= 1"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>

          <button type="button" class="btn-secondary" (click)="addTerm(ci)">
            Add term
          </button>
        </article>
      </section>

      <section class="config-section config-section--submit">
        <button type="submit">
          {{ isEdit ? "Save changes" : "Create organization" }}
        </button>
      </section>
    </form>
  </div>
</div>
